  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength); let offset = 12; let channels = 0, sampleRate = 0, bits = 0, dataOffset = 0, size = 0;
  while (offset + 8 <= bytes.length) { const name = new TextDecoder().decode(bytes.slice(offset, offset + 4)); const chunkSize = view.getUint32(offset + 4, true); const content = offset + 8; if (content + chunkSize > bytes.length) throw new Error("AUDIO_METADATA_INVALID"); if (name === "fmt ") { if (view.getUint16(content, true) !== 1) throw new Error("AUDIO_FORMAT_UNSUPPORTED"); channels = view.getUint16(content + 2, true); sampleRate = view.getUint32(content + 4, true); bits = view.getUint16(content + 14, true); } if (name === "data") { dataOffset = content; size = chunkSize; break; } offset = content + chunkSize + (chunkSize % 2); }
